UPDATE oa_meeting_reminder SET status = #{reminder.status}, sent_flag = #{reminder.sentFlag},
    send_time = #{reminder.sendTime}, message_record_id = #{reminder.messageRecordId},
    update_by = #{reminder.updateBy}, update_time = #{reminder.updateTime}
WHERE tenant_id = #{reminder.tenantId} AND reminder_id = #{reminder.reminderId}
